const cachedRequest = async (number: number, ion: number) =>
    unstable_cache(
        async () => Spectrum.findMany(number, ion),
        ['spectrum', number.toString(), ion.toString()],
        {
            revalidate: DAY_IN_SECONDS * 7,
        },
    )()

